     * 整个 Group 共享同一条时间轴：统一移动 / 高亮 / 反光，绝不拆成两条独立歌词。
     */
    var `lines`: List<kotlin.String>
    , 
    /**
     * 逐字时间戳（覆盖整个 Group 的拼接文本；LRC 无逐字时为空）
     */
    var `words`: List<LyricWord>
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeLyricLine: FfiConverterRustBuffer<LyricLine> {
    override fun read(buf: ByteBuffer): LyricLine {
        return LyricLine(
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterSequenceString.read(buf),
            FfiConverterSequenceTypeLyricWord.read(buf),
        )
    }

    override fun allocationSize(value: LyricLine) = (
            FfiConverterULong.allocationSize(value.`startTimeMs`) +
            FfiConverterULong.allocationSize(value.`endTimeMs`) +
            FfiConverterSequenceString.allocationSize(value.`lines`) +
            FfiConverterSequenceTypeLyricWord.allocationSize(value.`words`)
    )

    override fun write(value: LyricLine, buf: ByteBuffer) {
            FfiConverterULong.write(value.`startTimeMs`, buf)
            FfiConverterULong.write(value.`endTimeMs`, buf)
            FfiConverterSequenceString.write(value.`lines`, buf)
            FfiConverterSequenceTypeLyricWord.write(value.`words`, buf)
    }
}



