/**
 * 统一错误类型（Kotlin 可捕获并显示提示）
 */
sealed class MusicException(message: String): kotlin.Exception(message) {
        
        class NetworkException(message: String) : MusicException(message)
        
        class ApiException(message: String) : MusicException(message)
        
        class SongNotFound(message: String) : MusicException(message)
        
        class PlayUrlUnavailable(message: String) : MusicException(message)
        
        class LyricUnavailable(message: String) : MusicException(message)
        
        class ParseException(message: String) : MusicException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MusicException> {
        override fun lift(error_buf: RustBuffer.ByValue): MusicException = FfiConverterTypeMusicError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeMusicError : FfiConverterRustBuffer<MusicException> {
    override fun read(buf: ByteBuffer): MusicException {
        
            return when(buf.getInt()) {
            1 -> MusicException.NetworkException(FfiConverterString.read(buf))
            2 -> MusicException.ApiException(FfiConverterString.read(buf))
            3 -> MusicException.SongNotFound(FfiConverterString.read(buf))
            4 -> MusicException.PlayUrlUnavailable(FfiConverterString.read(buf))
            5 -> MusicException.LyricUnavailable(FfiConverterString.read(buf))
            6 -> MusicException.ParseException(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: MusicException): ULong {
        return 4UL
    }

    override fun write(value: MusicException, buf: ByteBuffer) {
        when(value) {
            is MusicException.NetworkException -> {
                buf.putInt(1)
                Unit
            }
            is MusicException.ApiException -> {
                buf.putInt(2)
                Unit
            }
            is MusicException.SongNotFound -> {
                buf.putInt(3)
                Unit
            }
            is MusicException.PlayUrlUnavailable -> {
                buf.putInt(4)
                Unit
            }
            is MusicException.LyricUnavailable -> {
                buf.putInt(5)
                Unit
            }
            is MusicException.ParseException -> {
                buf.putInt(6)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalTypeCurrentLyric: FfiConverterRustBuffer<CurrentLyric?> {
    override fun read(buf: ByteBuffer): CurrentLyric? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterTypeCurrentLyric.read(buf)
    }

    override fun allocationSize(value: CurrentLyric?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterTypeCurrentLyric.allocationSize(value)
        }
    }

    override fun write(value: CurrentLyric?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterTypeCurrentLyric.write(value, buf)
        }
    }
}




